package com.singularity.todo.adr.cli

/**
 * Which checkout this binary was built from.
 *
 * Read from `/adr-provenance.properties`, generated by
 * `:adr-cli:generateAdrProvenance`. The file being absent is a supported
 * state, not a failure: a build that ran without git — a source tarball, a CI
 * export — produces no sha, and refusing to print a version there would mean
 * the command that reports identity is the one that fails when identity is
 * unavailable.
 *
 * So a missing stamp reads as [UNKNOWN] rather than throwing, and `--check`
 * compares [UNKNOWN] with [UNKNOWN] and passes. That is the honest answer: the
 * binary makes no claim about which commit produced it, and a caller asking
 * "does this match my checkout?" cannot be told yes or no.
 */
object AdrProvenance {

    const val UNKNOWN: String = "unknown"

    private val properties: java.util.Properties? = run {
        val stream = AdrProvenance::class.java.getResourceAsStream("/adr-provenance.properties")
        stream?.use { java.util.Properties().apply { load(it) } }
    }

    /** 12-char git sha of HEAD at build time, or [UNKNOWN]. */
    val gitSha: String = properties?.getProperty("gitSha")?.takeIf { it.isNotBlank() } ?: UNKNOWN

    /** `clean` or `dirty`, scoped to the three ADR modules. */
    val gitDirty: String = properties?.getProperty("gitDirty")?.takeIf { it.isNotBlank() } ?: UNKNOWN

    /** False when the build recorded no sha at all — see the class comment. */
    val isKnown: Boolean get() = gitSha != UNKNOWN

    /**
     * Whether this binary was built from [checkoutSha].
     *
     * `dirty` does not make a binary mismatched: a build from a worktree with
     * uncommitted edits is still a build of *that* commit plus those edits, and
     * refusing to compare would make `--check` useless for every worktree that
     * has not been committed — which is most of them, most of the time.
     */
    fun matches(checkoutSha: String): Boolean =
        isKnown && gitSha.equals(checkoutSha.trim().take(12), ignoreCase = true)
}